CREATE TABLE IF NOT EXISTS component_catalog (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, manufacturer TEXT, category TEXT NOT NULL, subcategory TEXT, description TEXT NOT NULL DEFAULT '', package_name TEXT, pinout_json TEXT NOT NULL DEFAULT '[]', specifications_json TEXT NOT NULL DEFAULT '{}', applications_json TEXT NOT NULL DEFAULT '[]', limitations_json TEXT NOT NULL DEFAULT '[]', precautions_json TEXT NOT NULL DEFAULT '[]', datasheet_url TEXT, verification_state TEXT NOT NULL DEFAULT 'pending', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_items (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, catalog_id TEXT REFERENCES component_catalog(id), code TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), location TEXT NOT NULL DEFAULT '', condition TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_movements (id TEXT PRIMARY KEY, inventory_id TEXT NOT NULL REFERENCES inventory_items(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, delta INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS component_measurements (id TEXT PRIMARY KEY, inventory_id TEXT NOT NULL REFERENCES inventory_items(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, quantity_name TEXT NOT NULL, value TEXT NOT NULL, unit TEXT NOT NULL, instrument TEXT NOT NULL DEFAULT '', conditions TEXT NOT NULL DEFAULT '', measured_at TEXT NOT NULL, result TEXT NOT NULL DEFAULT '', observations TEXT NOT NULL DEFAULT '', evidence_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS project_components (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, inventory_id TEXT REFERENCES inventory_items(id), code TEXT NOT NULL, reference_designator TEXT NOT NULL, planned_quantity INTEGER NOT NULL CHECK(planned_quantity>0), purpose TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
